import{z as A,x as p,o as s,c as B,q as E,j as o,D as t,d as n,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"Patterson / Hennessy","description":"","frontmatter":{"title":"Patterson / Hennessy","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/patterson-hennessy.md","filePath":"cs/patterson-hennessy.md","lastUpdated":1791063341000}'),d={name:"cs/patterson-hennessy.md"};function h(C,a,c,m,P,f){const r=p("Mermaid");return s(),B("div",null,[a[2]||(a[2]=E('<h1 id="patterson-hennessy" tabindex="-1">Patterson / Hennessy <a class="header-anchor" href="#patterson-hennessy" aria-label="Permalink to &quot;Patterson / Hennessy&quot;">​</a></h1><div class="epigraph"><p>用 CPI、Amdahl 与层次化存储把「快」写成可算的数；ISA 与实现分开，量化先于故事。</p><footer>—— Patterson and Hennessy, Computer Organization and Design；Hennessy and Patterson, Computer Architecture: A Quantitative Approach</footer></div><p><a href="/cs/diffie-hellman-paper">上一课</a>附录对照了公钥方向。附录对照，不插入主干。主干已在<a href="/cs/diffie-hellman-paper">流水线五级</a>、<a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a>、<a href="/cs/locality-principle">局部性</a>、Cache 与一致性各课用过量化方法；这里对照 <strong>这两本教材的问题</strong>：如何把组成与体系结构收成可教的定量栈，而不是厂商故事。不重画五级流水线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EDVAC 草稿给了存储程序；主干从门走到乱序。Patterson/Hennessy 的缺口是教材结构：指令集作为契约，实现用流水线与存储层次去堆 CPI，用 Amdahl 挡住「只加速一部分」。RISC-V 进入后版 COD，主干<a href="/cs/riscv-int-isa">RISC-V 整数指令</a>已选它当 ISA，不必回到 MIPS 课序。</p><p><span class="marginnote">「CPI」翻译成白话：每条指令平均要花几个时钟周期。数字实例：程序 10 亿条指令、CPI = 1.5、主频 1 GHz（周期 1 ns），CPU 时间 = 10^9 × 1.5 × 1 ns = 1.5 秒。三个因子各管一摊：编译器管指令数，微结构管 CPI，工艺管周期。</span></p><p><span class="marginnote">两本书分工：COD 偏组成与教学机器；CA:AQA 偏量化与多核、向量。主干课序把它们拆进组成课与体系结构课，附录对照方法而不是目录。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先定义性能（延迟、吞吐、CPI），再引入流水线冒险、Cache 缺失分类、一致性协议。主干<a href="/cs/mesi-protocol">MESI</a>、<a href="/cs/memory-consistency">存储一致性</a>已按这条量化链取用。附录不把某一年附录里的具体处理器型号插进主干——型号是附录级，规则已写明。</p>',9)),(s(),o(l,null,{default:t(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISA%5B%22ISA%20%E5%A5%91%E7%BA%A6%22%5D%20--%3E%20IMP%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%20%2F%20%E5%AD%98%E5%82%A8%E5%B1%82%E6%AC%A1%22%5D%0A%20%20IMP%20--%3E%20MET%5B%22CPI%20%2F%20Amdahl%22%5D%0A%20%20IMP%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E7%BB%84%E6%88%90%E4%B8%8E%E4%BD%93%E7%B3%BB%E7%BB%93%E6%9E%84%E8%AF%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"量化迫使「局部性」「缺失类型」「转发」成为可考对象，而不是示意图。主干严格按树上课，教材章节顺序不必等于课序（本栏先流水线后 Cache，与常见教学一致，但不为赶教材而插入型号）。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"Amdahl 数字实例：程序 90% 的时间在一个部分上，把这部分加速 10 倍，总加速 = \\(1/(0.1 + 0.9/10) \\approx 5.3\\) 倍，不是 10 倍；哪怕这部分加速到无穷快，上限也只有 \\(1/0.1 = 10\\) 倍。这就是「用 Amdahl 挡住只加速一部分」的准确含义。")],-1)),(s(),o(l,null,{default:t(()=>[i(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22CPU%20%E6%97%B6%E9%97%B4%20%3D%20%E6%8C%87%E4%BB%A4%E6%95%B0%20%C3%97%20CPI%20%C3%97%20%E6%97%B6%E9%92%9F%E5%91%A8%E6%9C%9F%22%5D%20--%3E%20IC%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%20%2F%20%E7%AE%97%E6%B3%95%EF%BC%9A%E5%8E%8B%E6%8C%87%E4%BB%A4%E6%95%B0%22%5D%0A%20%20T%20--%3E%20CPI%5B%22%E5%BE%AE%E7%BB%93%E6%9E%84%EF%BC%9A%E6%B5%81%E6%B0%B4%E7%BA%BF%E4%B8%8E%E8%BD%AC%E5%8F%91%E9%99%8D%20CPI%22%5D%0A%20%20T%20--%3E%20CLK%5B%22%E5%B7%A5%E8%89%BA%EF%BC%9A%E7%BC%A9%E7%9F%AD%E6%97%B6%E9%92%9F%E5%91%A8%E6%9C%9F%22%5D%0A%20%20IC%20--%3E%20AM%5B%22Amdahl%EF%BC%9A%E6%80%BB%E5%8A%A0%E9%80%9F%E5%8F%97%E6%9C%AA%E5%8A%A0%E9%80%9F%E9%83%A8%E5%88%86%E9%99%90%E5%88%B6%22%5D%0A%20%20CPI%20--%3E%20AM%0A%20%20CLK%20--%3E%20MEM%5B%22%E5%AD%98%E5%82%A8%E5%A2%99%EF%BC%9A%E5%91%A8%E6%9C%9F%E5%BF%AB%E4%BA%86%EF%BC%8CCache%20%E7%BC%BA%E5%A4%B1%E6%9B%B4%E8%B4%B5%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p>初学者容易以为主频翻倍程序就快一倍。实际上周期变短后，一次 Cache 缺失占用的周期数反而更多（存储墙），且 Amdahl 上限压着整体收益——频率是三个因子之一，不是全部。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若按某版 COD 章节替换本栏树，向量、虚拟化会打乱「从比特到安全」的深度优先。附录对照定量方法的出处，型号与具体微结构世代不进主干。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 Hennessy/Patterson 图灵奖演说当另一本教材。下一篇对照龙书如何把编译收成通行证与形式化前端，主干编译课已经按通行证走。</p><p>量化方法不自动给出乱序与 SIMD 的正确性；那些课仍要冒险与向量模型，教材只提供测量框架。</p><p>对照结束应回到主干流水线与 Cache 课的量化尺子。具体处理器型号仍不进入主干。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>附录对照，不插入主干。</p></li><li><p>下一篇对照龙书编译通行证。</p></li><li><p>附录对照 Patterson/Hennessy：ISA 与实现分离，性能可量化。</p></li><li><p>主干流水线、CPI、Cache、一致性已取用；型号不进主干。</p></li><li><p>不按某版教材目录重排课序。</p></li><li><p>出处：<em>Computer Organization and Design</em>；<em>Computer Architecture: A Quantitative Approach</em>。</p></li></ul>',9))])}const D=A(d,[["render",h]]);export{I as __pageData,D as default};
